# PowerShell script to set up and run the FastAPI applicationnn$VenvDir = "venv"n$RequirementsFile = "requirements.txt"nnWrite-Host "--- Initializing Python Virtual Environment ---"nn# Check if virtual environment existsnif (-not (Test-Path -Path $VenvDir -PathType Container)) {n    Write-Host "Creating virtual environment '$VenvDir'..."n    python -m venv $VenvDirn} else {n    Write-Host "Virtual environment '$VenvDir' already exists."n}nn# Activate virtual environmentnWrite-Host "Activating virtual environment..."nif (Test-Path -Path ".\$VenvDir\Scripts\Activate.ps1") {n    .".\$VenvDir\Scripts\Activate.ps1"n} elseif (Test-Path -Path ".\$VenvDir\Scripts\activate") { # For non-PowerShell activatorsn    .".\$VenvDir\Scripts\activate"n} else {n    Write-Host "Error: Could not find activate script for virtual environment." -ForegroundColor Redn    exit 1n}nn# Install dependenciesnif (Test-Path -Path $RequirementsFile) {n    Write-Host "Installing dependencies from '$RequirementsFile'..."n    pip install --no-cache-dir -r $RequirementsFilen    Write-Host "Dependencies installed successfully."n} else {n    Write-Host "Warning: '$RequirementsFile' not found. Skipping dependency installation." -ForegroundColor Yellown}nn# Run the FastAPI applicationnWrite-Host "Starting FastAPI application with Uvicorn..."nWrite-Host "Access the API documentation at http://127.0.0.1:8000/docs"ncd app; uvicorn main:app --host 0.0.0.0 --port 8000 --reload --log-level info